package ru.mail.march

import androidx.lifecycle.LifecycleOwner
import ru.mail.march.channel.*

class TestDataChannelFactory(private val owner: LifecycleOwner) :
    DataChannelFactory {

    private val channels = ArrayList<LiveDataChannel<*>>()

    override fun <T> createStateChannel(comparator: StateComparator<T>): DataChannel<T> {
        return StateDataChannel(comparator).also {
            it.attachOwner(owner)
            channels.add(it)
        }
    }

    override fun <T> createEventChannel(): DataChannel<T> {
        return EventDataChannel<T>().also {
            it.attachOwner(owner)
            channels.add(it)
        }
    }
}

package ru.mail.march.interactor

import androidx.arch.core.executor.testing.InstantTaskExecutorRule
import androidx.lifecycle.Observer
import com.nhaarman.mockitokotlin2.mock
import com.nhaarman.mockitokotlin2.times
import com.nhaarman.mockitokotlin2.verify
import org.junit.Rule
import org.junit.Test
import ru.mail.march.TestInteractor

class InteractorTest {

    @get:Rule
    val rule = InstantTaskExecutorRule()

    private val eventObserver: Observer<String> = mock()
    private val stateObserver: Observer<Int> = mock()


    @Test
    fun `observe events and states`() {
        val interactor = SampleInteractor()
        interactor.eventDataChannel.observe {
            eventObserver.onChanged(it)
        }

        interactor.stateDataChannel.observe {
            stateObserver.onChanged(it)
        }

        interactor.eventDataChannel.postValue("event")
        verify(eventObserver, times(1)).onChanged("event")

        interactor.stateDataChannel.postValue(1)
        verify(stateObserver, times(1)).onChanged(1)
    }
}

class SampleInteractor : TestInteractor() {
    val eventDataChannel = eventChannel<String>()
    val stateDataChannel = eventChannel<Int>()
}

package ru.mail.march.channel

import androidx.arch.core.executor.testing.InstantTaskExecutorRule
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleOwner
import androidx.lifecycle.LifecycleRegistry
import androidx.lifecycle.Observer
import com.nhaarman.mockitokotlin2.mock
import com.nhaarman.mockitokotlin2.times
import com.nhaarman.mockitokotlin2.verify
import com.nhaarman.mockitokotlin2.whenever
import org.junit.Rule
import org.junit.Test

class EventUnitTest {

    @get:Rule
    val rule = InstantTaskExecutorRule()

    private val observer: Observer<String> = mock()

    @Test
    fun `notify with all values (not a unique)`() {
        val channelEvent = getEventChannelForTest<String>()

        channelEvent.observe {
            observer.onChanged(it)
        }

        channelEvent.postValue("event")

        verify(observer, times(1)).onChanged("event")

        channelEvent.postValue("event")

        verify(observer, times(2)).onChanged("event")
    }

    @Test
    fun `observer will be notified with last event in channel`() {
        val channelEvent = getEventChannelForTest<String>()

        channelEvent.postValue("event")

        channelEvent.observe {
            observer.onChanged(it)
        }

        verify(observer).onChanged("event")
    }


    @Test
    fun `observer will not be notified, if event already observed`() {
        val channelEvent = getEventChannelForTest<String>()

        channelEvent.postValue("event")

        channelEvent.observe {
            observer.onChanged(it)
        }

        val mockObserver: Observer<String> = mock()
        channelEvent.observe {
            mockObserver.onChanged(it)
        }

        verify(mockObserver, times(0)).onChanged("event")
    }

    private fun <T> getEventChannelForTest(): DataChannel<T> {
        val owner = mock<LifecycleOwner>()

        val lifecycleRegistry = LifecycleRegistry(owner)
        whenever(owner.lifecycle).thenReturn(lifecycleRegistry)

        val channelFactory = LiveDataChannelFactory()
        val channelEvent = channelFactory.createEventChannel<T>()

        channelFactory.attachOwner(owner)

        lifecycleRegistry.handleLifecycleEvent(Lifecycle.Event.ON_RESUME)
        return channelEvent
    }
}

package ru.mail.march.channel

import androidx.arch.core.executor.testing.InstantTaskExecutorRule
